 static void BowlingScreens(GameForm f,string evidence){Set(f,"matchFixture",-1);Franchise club=Franchise.Create(new Profile(),new Roster());Set(f,"franchise",club);club.Save();string saved=File.ReadAllText(Franchise.SavePath);Set(f,"screen","home");Set(f,"selection",2);f.SavePreview(Path.Combine(evidence,"menu.png"));Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="bowlsetup","Bowling is selectable directly from main menu");f.SavePreview(Path.Combine(evidence,"bowling-setup.png"));Set(f,"selection",0);Call(f,"ActivateSelection");Set(f,"selection",1);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="bowlsetup"&&(int)Get(f,"quickHome")==1,"Bowling team selection returns to Bowling setup");Set(f,"selection",4);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="bowlrules","Bowling explains rules before first attempt");f.SavePreview(Path.Combine(evidence,"bowling-rules.png"));Call(f,"ActivateSelection");Simulation s=(Simulation)Get(f,"game");Check(s.Bowling&&s.Spot==90&&s.Players.Count==22,"Bowling begins at opponent ten against real defense");f.SavePreview(Path.Combine(evidence,"bowling-field.png"));s.Snap();s.Controlled.Z=101;s.Update(.02f,0,0);Step(f,Keys.None,false,1);FootballBowling match=(FootballBowling)Get(f,"bowlingMatch");Check((string)Get(f,"screen")=="bowlcard"&&match.Turn==1&&match.Cards[0].Marks(0)=="X","first-play TD records strike and alternates teams");f.SavePreview(Path.Combine(evidence,"bowling-scorecard.png"));Set(f,"selection",0);Call(f,"ActivateSelection");for(int n=0;n<650&&(string)Get(f,"screen")=="game";n++){s=(Simulation)Get(f,"game");if(s.AmbulanceActive)s.SkipAmbulance();Step(f,Keys.None,false,1);}Check((string)Get(f,"screen")=="bowlcard"&&match.RollCount==2,"CPU completes real on-field offensive attempt");f.SavePreview(Path.Combine(evidence,"bowling-cpu-result.png"));while(!match.Complete)match.Record(0);Set(f,"screen","bowlcard");f.SavePreview(Path.Combine(evidence,"bowling-final.png"));Check(match.Cards[0].Complete&&match.Cards[1].Complete,"both teams finish all frames before result");Set(f,"screen","bowlsetup");Set(f,"selection",2);Call(f,"ActivateSelection");Set(f,"selection",4);Call(f,"ActivateSelection");Call(f,"ActivateSelection");match=(FootballBowling)Get(f,"bowlingMatch");s=(Simulation)Get(f,"game");Check(match.TwoPlayers&&match.Turn==0,"local two-player mode uses alternating shared controls");s.Snap();s.Controlled.Z=101;s.Update(.02f,0,0);Step(f,Keys.None,false,1);Set(f,"selection",0);Call(f,"ActivateSelection");s=(Simulation)Get(f,"game");Check(match.Turn==1&&s.State==Phase.PreSnap&&s.Franchise.UserTeam==match.Teams[1],"player two gets playable offense with his own team roster");Check(File.ReadAllText(Franchise.SavePath)==saved,"Bowling leaves real franchise save unchanged");Set(f,"bowlingMatch",null);Set(f,"screen","home");Set(f,"matchFixture",-1);}
}
